import pandas as pd

def clean(df):
    df = df.drop_duplicates().reset_index(drop=True)
    df['body_mass_g'] = df['body_mass_g'].str.replace(',', '', regex=False).astype(float)
    return df

def answer(df):
    result = df.groupby('species')['body_mass_g'].sum()
    return result.to_dict()
